<script>
 import {at,format,finite,timeLabel,HOUR} from './engine.mjs';
 import {seriesGeometry} from './visuals.mjs';
 import {browseFields,fieldSummary,explainField} from './parameter-browser.mjs';
 export let fields=[],valid,prefs={},pins=[],served='',selected=null,query='',onPin=()=>{},onTime=()=>{},onExport=()=>{};
 let group='All',level='All',scope='all',horizon='48',page=0;
 $: groups=['All','Temperature',...new Set(fields.map(f=>f.group))];
 $: levels=[...new Set(fields.flatMap(f=>f.key.match(/-(\d+)h$/)?.[1]||[]))].sort((a,b)=>Number(b)-Number(a));
 $: filtered=browseFields(fields,{query,group,level,scope,pins,valid});
 $: mini=new Map(filtered.map(f=>[f.id,seriesGeometry(f,valid,valid+24*HOUR)]));
 $: active=fields.find(f=>f.id===selected);
 $: end=horizon==='all'?Math.max(valid,...(active?.ts||[])):valid+Number(horizon)*HOUR;
 $: stats=active?fieldSummary(active,valid,end):null;
 $: chart=active?seriesGeometry(active,valid,end):null;
 $: chartable=active&&!['raw','code','boolean','°'].includes(active.unit)&&chart.points.filter(p=>finite(p.v)).length>1;
 $: pages=Math.max(1,Math.ceil((stats?.samples.length||0)/24));
 $: safePage=Math.min(page,pages-1);
 $: samples=stats?.samples.slice(safePage*24,(safePage+1)*24)||[];
 function open(id){selected=selected===id?null:id;page=0;}
 function reset(){query='';group='All';level='All';scope='all';}
</script>
<section class="parameter-browser" aria-label="Parameter library">
 <div class="heading"><div><h2>Parameter library</h2><p>Open a field for details · mini trends show the next 24 hours.</p></div><button on:click={onExport}>Export JSON ↓</button></div>
 <div class="search"><input type="search" aria-label="Search parameters" placeholder="Search temperature, wind, 850…" bind:value={query}/>{#if query}<button aria-label="Clear parameter search" on:click={()=>query=''}>×</button>{/if}</div>
 <div class="filters"><label>Category<select aria-label="Parameter category" bind:value={group}>{#each groups as g}<option>{g}</option>{/each}</select></label><label>Level<select aria-label="Pressure level" bind:value={level}><option value="All">All levels</option>{#each levels as p}<option value={p}>{p} hPa</option>{/each}</select></label></div>
 <div class="scopes" role="group" aria-label="Parameter availability">{#each [['all','All'],['pinned','★ Pinned'],['available','Available'],['missing','Missing']] as [key,label]}<button aria-pressed={scope===key} class:chosen={scope===key} on:click={()=>scope=key}>{label}</button>{/each}</div>
 <div class="count"><span>{filtered.length} of {fields.length} fields · {served}</span><button on:click={reset}>Reset filters</button></div>
 {#if !filtered.length}<div class="empty"><h3>No matching parameters</h3><p>Try fewer search words or reset the filters.</p><button on:click={reset}>Show all parameters</button></div>{/if}
 {#each filtered as f (f.id)}
 <article class:expanded={selected===f.id}>
  <div class="row"><button class="field" aria-expanded={selected===f.id} aria-controls={'field-'+f.id} on:click={()=>open(f.id)}><span><b>{f.label}</b><small>{f.group} · {f.section}</small></span>{#if !['raw','code','boolean','°'].includes(f.unit)&&mini.get(f.id)?.path}<svg class="spark" viewBox="40 15 510 155" aria-hidden="true"><path d={mini.get(f.id).path} fill="none" stroke="currentColor" stroke-width="7"/></svg>{/if}<span class="value">{format(at(f,valid),f.unit,prefs)} <i>{selected===f.id?'−':'+'}</i></span></button><button class="pin" class:pinned={pins.includes(f.key)} aria-pressed={pins.includes(f.key)} aria-label={`Pin ${f.label} ${f.section}`} on:click={()=>onPin(f.key)}>{pins.includes(f.key)?'★':'☆'}</button></div>
  {#if selected===f.id&&active&&stats}<div class="detail" id={'field-'+f.id}>
   <p>{explainField(f)}</p>
   {#if f.unit==='°'&&finite(at(f,valid))}<div class="special-visual"><svg viewBox="0 0 120 120" role="img" aria-label={f.label+' '+format(at(f,valid),f.unit,prefs)}><circle cx="60" cy="60" r="40" fill="none" stroke="#36505e"/><text x="60" y="10" text-anchor="middle">N</text><text x="112" y="64" text-anchor="middle">E</text><text x="60" y="117" text-anchor="middle">S</text><text x="8" y="64" text-anchor="middle">W</text><path d="M60 28 L52 67 L60 62 L68 67 Z" fill="#7be4ca" transform={'rotate('+at(f,valid)+' 60 60)'}/></svg><p>{f.key.startsWith('windDir')?'Wind comes from the indicated direction.':'Direction in degrees; consult the provider convention.'}</p></div>{:else if f.unit==='%'&&finite(at(f,valid))&&at(f,valid)>=0&&at(f,valid)<=100}<div class="special-visual"><svg viewBox="0 0 120 120" role="img" aria-label={f.label+' '+format(at(f,valid),f.unit,prefs)}><circle cx="60" cy="60" r="44" fill="none" stroke="#36505e" stroke-width="7"/><circle cx="60" cy="60" r="44" fill="none" stroke="#7be4ca" stroke-width="7" pathLength="100" stroke-dasharray={at(f,valid)+' 100'} transform="rotate(-90 60 60)"/><text x="60" y="65" text-anchor="middle" class="ring-value">{format(at(f,valid),'%',prefs)}</text></svg><p>{f.label} · selected time</p></div>{/if}<div class="facts"><div><small>Selected forecast</small><strong>{format(at(f,valid),f.unit,prefs)}</strong></div><div><small>Valid time · {prefs.local?'device local':'UTC'}</small><strong>{timeLabel(valid,prefs.local)}</strong></div></div>
   <p class="availability">{at(f,valid)==null?'Unavailable at this exact forecast time. Choose a supplied timestamp below.':'Value supplied at this exact forecast time.'}</p>
   <label class="horizon">Browse forecast<select aria-label={`Forecast range for ${f.label}`} bind:value={horizon} on:change={()=>page=0}><option value="24">Next 24 hours</option><option value="48">Next 48 hours</option><option value="all">All remaining times</option></select></label>
   {#if chartable}<svg viewBox="0 0 584 205" role="img" aria-label={`${f.label} forecast trend in ${f.unit}; missing samples are not connected`}><text x="48" y="14">{format(chart.max,f.unit,prefs)}</text><text x="48" y="181">{format(f.unit.startsWith('mm')?0:chart.min,f.unit,prefs)}</text>{#if f.unit.startsWith('mm')}{#each chart.points.filter(p=>finite(p.v)) as p}<rect x={p.x-2} y={154-Math.max(0,p.v)/Math.max(1,chart.max)*130} width="4" height={Math.max(0,p.v)/Math.max(1,chart.max)*130} fill="#7be4ca"/>{/each}{:else}<path d={chart.path} fill="none" stroke="#7be4ca" stroke-width="2.5"/>{/if}<text x="48" y="200">{timeLabel(valid,prefs.local)}</text><text x="536" y="200" text-anchor="end">{timeLabel(end,prefs.local)}</text></svg>{:else}<p>Use the values below for this field. A continuous trend is not shown for categorical, unmapped, directional or single-sample data.</p>{/if}
   <div class="facts"><div><small>Available samples</small><strong>{stats.available} / {stats.total}</strong></div>{#if !['raw','code','boolean','°'].includes(f.unit)}<div><small>Range in this window</small><strong>{format(stats.min,f.unit,prefs)} — {format(stats.max,f.unit,prefs)}</strong></div>{/if}</div>
   <div class="coverage-strip" aria-label="Forecast availability timeline">{#each stats.samples as p}<button class:missing={p.value===null||(typeof p.value==='number'&&!finite(p.value))} class:current={p.time===valid} title={timeLabel(p.time,prefs.local)+' · '+format(p.value,f.unit,prefs)} aria-label={'Select '+timeLabel(p.time,prefs.local)+': '+format(p.value,f.unit,prefs)} on:click={()=>onTime(p.time)}></button>{/each}</div><p class="strip-key">Sample timeline · mint = supplied · outlined = missing · tap to select</p><details><summary>Forecast values · {stats.total} timestamps</summary><div class="table"><table><thead><tr><th>Time · {prefs.local?'local':'UTC'}</th><th>Value</th></tr></thead><tbody>{#each samples as p}<tr class:current={p.time===valid}><td><button on:click={()=>onTime(p.time)}>{timeLabel(p.time,prefs.local)}</button></td><td>{format(p.value,f.unit,prefs)}</td></tr>{/each}</tbody></table></div>{#if pages>1}<div class="pager"><button disabled={safePage===0} on:click={()=>page=safePage-1}>Previous</button><span>{safePage+1} / {pages}</span><button disabled={safePage===pages-1} on:click={()=>page=safePage+1}>Next</button></div>{/if}</details>
   <details><summary>Source & original value</summary><dl><dt>Source</dt><dd>{served} · {f.section}</dd><dt>Field</dt><dd>{f.key}</dd><dt>Provider unit</dt><dd>{f.unit}</dd><dt>First / last timestamp</dt><dd>{timeLabel(f.ts[0],prefs.local)} / {timeLabel(f.ts[f.ts.length-1],prefs.local)}</dd></dl><pre>{JSON.stringify(at(f,valid),null,2)??'Not supplied'}</pre><p>Original values and exports retain full precision. Display rounding does not change calculations.</p></details>
  </div>{/if}
 </article>{/each}
</section>
<style>
 .spark{width:58px;height:25px;flex:0 0 58px;color:#7be4ca;margin:0}.special-visual{display:flex;align-items:center;justify-content:center;gap:16px}.special-visual svg{width:110px;flex:0 0 110px}.special-visual p{max-width:160px}.ring-value{font-size:17px;fill:#edf7fa}.coverage-strip{display:grid;grid-template-columns:repeat(auto-fit,minmax(9px,1fr));gap:3px;margin-top:14px}.coverage-strip button{height:16px;min-height:16px;padding:0;border:1px solid #7be4ca;background:#3b9789;border-radius:3px}.coverage-strip button.missing{background:transparent;border-color:#637c88}.coverage-strip button.current{background:#edf7fa}.strip-key{font-size:10px}@media(max-width:390px){.spark{display:none}}.parameter-browser{color:var(--ink,#edf7fa);margin-top:18px;font:13px/1.5 system-ui}h2,h3,p{margin:0}h2{font-size:19px}p{font-size:12px;color:var(--muted,#b2c7d1);line-height:1.65;margin:8px 0}.heading,.count,.row,.pager{display:flex;align-items:center;justify-content:space-between;gap:8px}.heading{margin-bottom:14px}.heading button{white-space:nowrap}button,input,select{font:inherit;color:inherit;background:#152b37;border:1px solid #36505e;border-radius:8px;padding:9px;min-height:40px;max-width:100%;box-sizing:border-box}button{cursor:pointer}button:hover{background:#23434a}button:disabled{opacity:.4;cursor:default}button:focus-visible,input:focus-visible,select:focus-visible,summary:focus-visible{outline:2px solid #7be4ca;outline-offset:2px}.search{display:flex;gap:6px;position:sticky;top:0;z-index:2;background:#0d1b27;padding:5px 0}.search input{width:100%;min-width:0}.filters{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:10px 0}.filters label{font-size:11px;color:#b2c7d1}.filters select{display:block;width:100%;margin-top:4px}.scopes{display:flex;gap:5px;flex-wrap:wrap}.scopes button{flex:1;font-size:11px}.chosen{background:#244b4e;border-color:#7be4ca;color:#7be4ca}.count{font-size:11px;color:#b2c7d1;margin:12px 0}.count button{font-size:11px;background:none;border:0}article{border-bottom:1px solid #36505e}.expanded{border:1px solid #537b81;border-radius:10px;background:#122633;margin:8px 0}.row{gap:0}.field{display:flex;justify-content:space-between;align-items:center;gap:10px;width:100%;min-width:0;text-align:left;background:transparent;border:0;padding:13px 8px}.field b{font-weight:500;font-size:13px}.field small{display:block;font-size:10px;color:#b2c7d1}.field>span:first-child{min-width:0;overflow-wrap:anywhere}.value{white-space:nowrap;font-size:13px}.value i{font-style:normal;color:#7be4ca;padding-left:7px}.pin{font-size:22px;border:0;background:none;flex:0 0 38px;padding:5px}.pinned{color:#7be4ca}.detail{padding:0 12px 14px}.facts{display:grid;grid-template-columns:1fr 1fr;gap:12px;padding:12px 0}.facts small{display:block;font-size:10px;color:#b2c7d1}.facts strong{font-size:13px;font-weight:500}.horizon{display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:11px}.horizon select{font-size:11px}.availability{font-size:11px}svg{display:block;width:100%;margin:10px 0}svg text{fill:#b2c7d1;font-size:11px}details{padding:10px 0;border-top:1px solid #36505e;font-size:11px}summary{cursor:pointer;color:#7be4ca}.table{overflow:auto}table{width:100%;border-collapse:collapse;font-size:11px}th,td{padding:6px;text-align:right;border-bottom:1px solid #29444f}th:first-child,td:first-child{text-align:left}td button{background:none;border:0;font-size:11px;color:#7be4ca;padding:4px}.current{background:#23434a}.pager{margin-top:8px}.pager button{font-size:11px}dl{display:grid;grid-template-columns:90px 1fr;gap:8px}dt{color:#b2c7d1}dd{margin:0;overflow-wrap:anywhere}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#0d1b27;padding:10px}.empty{text-align:center;padding:30px 10px}
</style>
